//! The measured RakuAST type hierarchy.
//!
//! `hierarchy.tsv` lists every name in rakudo's `RakuAST::` package tree with
//! its kind (class, role or bare package), its `.^mro` and its `.^roles`, as
//! rakudo 2026.09 reports them. It is generated by
//! `scripts/rakuast-hierarchy.raku`, so regenerate it rather than editing it.
//! `.^mro`, `.^parents`, `.^roles`, `.^isa`, `.does` and smartmatch of a RakuAST
//! type object or node answer from this table, so the hierarchy a walker sees
//! (`when RakuAST::Term`, `~~ RakuAST::Literal`) is rakudo's, not a hand-kept
//! approximation.

use std::collections::HashMap;
use std::sync::LazyLock;

/// What kind of type object a `RakuAST::` name is.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Kind {
    Class,
    Role,
    /// A bare namespace (`RakuAST::IMPL`): no MRO, no roles.
    Package,
}

#[derive(Debug)]
pub(crate) struct Entry {
    pub(crate) kind: Kind,
    /// The ancestors after the type itself, without `Any`/`Mu`.
    pub(crate) mro: Vec<&'static str>,
    /// Every role the type does, transitively, in rakudo's order.
    pub(crate) roles: Vec<&'static str>,
}

static TABLE: LazyLock<HashMap<&'static str, Entry>> = LazyLock::new(|| {
    include_str!("hierarchy.tsv")
        .lines()
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .filter_map(|l| {
            let mut fields = l.split('\t');
            let name = fields.next()?;
            let kind = match fields.next()? {
                "class" => Kind::Class,
                "role" => Kind::Role,
                _ => Kind::Package,
            };
            let mro = fields.next().unwrap_or("").split_whitespace().collect();
            let roles = fields.next().unwrap_or("").split_whitespace().collect();
            Some((name, Entry { kind, mro, roles }))
        })
        .collect()
});

/// The measured entry for `name`, or `None` when rakudo has no such name.
///
/// Every measured name is in the `RakuAST` package tree, so any other name is
/// answered without building the table: a program that never touches RakuAST
/// must not pay for parsing it (#14869).
// Cost: O(1) expected, a prefix test and a hash lookup; the first RakuAST name
// builds the table once, O(n), n = rows in `hierarchy.tsv`.
pub(crate) fn entry(name: &str) -> Option<&'static Entry> {
    if !name.starts_with("RakuAST") {
        return None;
    }
    TABLE.get(name)
}

/// Whether `actual` lists `expected` in its MRO (`.^isa`): roles excluded.
/// `None` when `actual` is not a measured name.
// Cost: O(d), d = depth of `actual`'s MRO.
pub(crate) fn isa(actual: &str, expected: &str) -> Option<bool> {
    let e = entry(actual)?;
    Some(actual == expected || e.mro.contains(&expected))
}

/// Whether `actual` is a subtype of `expected` for smartmatch and `.does`:
/// itself, an MRO entry or a role it does. `None` when `actual` is not a
/// measured name.
// Cost: O(d + r), d = MRO depth, r = number of roles `actual` does.
pub(crate) fn does(actual: &str, expected: &str) -> Option<bool> {
    let e = entry(actual)?;
    Some(actual == expected || e.mro.contains(&expected) || e.roles.contains(&expected))
}

/// The full `.^mro` of `name` as rakudo prints it: the type itself, its
/// ancestors, then `Any` and `Mu` for a class; the role alone for a role.
// Cost: O(d), d = MRO depth.
pub(crate) fn mro(name: &str) -> Option<Vec<String>> {
    let e = entry(name)?;
    let mut out = vec![name.to_string()];
    if e.kind == Kind::Class {
        out.extend(e.mro.iter().map(|s| s.to_string()));
        out.push("Any".to_string());
        out.push("Mu".to_string());
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn literal_is_a_term_and_does_its_roles() {
        assert_eq!(isa("RakuAST::IntLiteral", "RakuAST::Literal"), Some(true));
        assert_eq!(isa("RakuAST::IntLiteral", "RakuAST::Sinkable"), Some(false));
        assert_eq!(does("RakuAST::IntLiteral", "RakuAST::Sinkable"), Some(true));
        assert_eq!(
            isa("RakuAST::StatementList", "RakuAST::Statement"),
            Some(false)
        );
        assert_eq!(isa("NotRakuAST", "RakuAST::Node"), None);
        assert!(entry("Int").is_none());
        assert!(entry("RakuAST").is_some());
    }

    #[test]
    fn role_mro_is_the_role_alone() {
        assert_eq!(
            mro("RakuAST::Code"),
            Some(vec!["RakuAST::Code".to_string()])
        );
        assert_eq!(entry("RakuAST::IMPL").map(|e| e.kind), Some(Kind::Package));
    }
}
